// Gmail en Outlook leveren een ander bericht-object. Hier wordt het één vorm,
// zodat alles erna niet hoeft te weten waar een mail vandaan kwam.
//
// Bijlagen: n8n zet ze in item.binary, met .data al base64. Alleen PDF's gaan
// mee; een logo van 4 kB in de handtekening is geen factuur en kost wel tokens.
const MAX_PDFS = 3;
const MAX_PDF_BYTES = 4 * 1024 * 1024; // Claude weigert grotere documenten
const out = [];

for (const item of $input.all()) {
  const j = item.json || {};
  const bin = item.binary || {};

  // Outlook heeft receivedDateTime + from.emailAddress; Gmail heeft threadId en
  // (met simple:false) headers. Beide varianten worden hier afgevangen.
  const isOutlook = !!j.receivedDateTime || !!j.bodyPreview;
  const headers = j.headers || {};
  const subject = j.subject || headers.subject || '';
  const from = isOutlook
    ? (j.from && j.from.emailAddress ? (j.from.emailAddress.address || '') : '')
    : (headers.from || j.From || '');
  const date = j.receivedDateTime || headers.date || j.internalDate || '';
  const text = String(j.text || j.bodyPreview || j.snippet || (j.body && j.body.content) || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 6000);

  const pdfs = [];
  for (const key of Object.keys(bin)) {
    const b = bin[key];
    if (!b || !b.data) continue;
    const type = String(b.mimeType || '').toLowerCase();
    const name = String(b.fileName || key);
    if (type !== 'application/pdf' && !/\.pdf$/i.test(name)) continue;
    // base64 is ~4/3 van de bytes; zo weten we de grootte zonder te decoderen.
    if ((b.data.length * 3) / 4 > MAX_PDF_BYTES) continue;
    pdfs.push({ name, data: b.data });
    if (pdfs.length >= MAX_PDFS) break;
  }

  out.push({ json: {
    source: isOutlook ? 'outlook' : 'gmail',
    messageId: String(j.id || j.messageId || ''),
    subject, from, date, text, pdfs,
    // Zonder PDF én zonder bruikbare tekst valt er niets te lezen.
    ok: pdfs.length > 0 || text.length > 40,
  } });
}
return out;

// Het verzoek aan Claude wordt HIER opgebouwd, niet in een expressie op de
// HTTP-node: met base64-PDF's erin wordt die expressie onleesbaar en is een
// fout er niet meer uit te halen.
//
// De PDF gaat als document-blok mee. Een factuur is een LAYOUT — bedragen staan
// in kolommen, btw staat onderaan — en die layout overleeft het platslaan naar
// tekst niet. Het model moet de pagina zien.
const SYSTEM = [
  'Je leest e-mails en bijlagen en bepaalt of er een FACTUUR in zit.',
  'Antwoord UITSLUITEND met JSON, zonder uitleg eromheen:',
  '{"isInvoice": true|false, "invoiceNumber": string|null, "issueDate": "YYYY-MM-DD"|null,',
  ' "dueDate": "YYYY-MM-DD"|null, "amount": number|null, "vatAmount": number|null,',
  ' "currency": "EUR", "counterparty": string|null, "direction": "expense"|"income"|null,',
  ' "note": string}',
  'amount is het TOTAAL inclusief btw, als getal, punt als decimaalteken, zonder valutateken.',
  'vatAmount is alleen het btw-bedrag.',
  'direction: "expense" als iemand GELD VAN JOU wil, "income" als jij iemand factureert.',
  'Laat een veld null als het er niet staat. Verzin nooit een bedrag of een nummer:',
  'een verzonnen factuur in een boekhouding is erger dan een gemiste factuur.',
  'Een betaalherinnering, aanmaning of orderbevestiging zonder bedrag is GEEN factuur:',
  'zet dan isInvoice op false.',
].join(' ');

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const content = [];
  for (const pdf of (j.pdfs || [])) {
    content.push({
      type: 'document',
      source: { type: 'base64', media_type: 'application/pdf', data: pdf.data },
    });
  }
  content.push({
    type: 'text',
    text: 'Onderwerp: ' + j.subject + '\nAfzender: ' + j.from + '\nDatum: ' + j.date +
          '\nBijlagen: ' + (j.pdfs || []).map((p) => p.name).join(', ') +
          '\n\n' + j.text,
  });

  out.push({ json: {
    source: j.source,
    messageId: j.messageId,
    subject: j.subject,
    body: {
      model: 'claude-sonnet-5',
      max_tokens: 1024,
      system: SYSTEM,
      messages: [{ role: 'user', content }],
    },
  } });
}
return out;

// Het antwoord van Claude naar de vorm die LaVega verwacht.
//
// De HTTP-node stuurt 1-op-1 door, dus item i hoort bij verzoek i uit
// "Bouw Claude-verzoek". Daar staan onderwerp en messageId, die Claude niet
// terugstuurt.
const asked = $('Bouw Claude-verzoek').all();
const items = $input.all();
const invoices = [];

const money = (v) => (typeof v === 'number' && isFinite(v) ? Math.round(v * 100) : null);
const isoDate = (v) => (typeof v === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(v) ? v : null);

for (let i = 0; i < items.length; i++) {
  const src = asked[i] ? asked[i].json : null;
  if (!src) continue;
  const text = items[i] && items[i].json && items[i].json.content && items[i].json.content[0]
    ? items[i].json.content[0].text : '';
  const match = typeof text === 'string' ? text.match(/\{[\s\S]*\}/) : null;
  if (!match) continue;
  let p;
  try { p = JSON.parse(match[0]); } catch (e) { continue; }

  // Zonder bedrag valt er niets in te boeken, en zonder bedrag kan LaVega ook
  // niet controleren of het klopt. Die weigeren we hier al.
  const amountCents = money(p.amount);
  if (p.isInvoice !== true || amountCents === null) continue;

  invoices.push({
    source: src.source,
    messageId: src.messageId,
    subject: String(src.subject || '').slice(0, 200),
    invoiceNumber: typeof p.invoiceNumber === 'string' ? p.invoiceNumber.slice(0, 60) : null,
    issueDate: isoDate(p.issueDate),
    dueDate: isoDate(p.dueDate),
    amountCents,
    vatCents: money(p.vatAmount),
    currency: typeof p.currency === 'string' && /^[A-Z]{3}$/.test(p.currency) ? p.currency : 'EUR',
    counterparty: typeof p.counterparty === 'string' ? p.counterparty.slice(0, 120) : null,
    direction: p.direction === 'income' ? 'income' : 'expense',
    note: typeof p.note === 'string' ? p.note.slice(0, 400) : undefined,
  });
}

// Eén verzoek met alles erin: LaVega zet ze in een wachtrij die JIJ bevestigt.
// Er wordt niets automatisch geboekt.
return [{ json: { invoices } }];

// De rij blijft HIER staan, in n8n, niet op de LaVega-server.
//
// Dat is het hele punt van deze opzet: een factuurbedrag is van jou, en de
// LaVega-server hoeft het nooit te zien. De browser haalt de rij straks
// rechtstreeks bij deze workflow op. Het pad is dus: jouw mailbox -> jouw n8n
// -> jouw browser. Geen enkele stap daarbuiten.
//
// getWorkflowStaticData overleeft een run, want n8n bewaart het bij de workflow
// in zijn eigen database.
const store = $getWorkflowStaticData('global');
if (!Array.isArray(store.queue)) store.queue = [];

const MAX_QUEUE = 200;
const seen = new Set(store.queue.map((r) => r.messageId));
let added = 0;

for (const item of $input.all()) {
  for (const inv of (item.json.invoices || [])) {
    // Dedup op messageId: de schedule loopt elk uur over dezelfde 7 dagen mail,
    // dus zonder dit staat elke factuur er na een dag 24 keer in.
    if (!inv.messageId || seen.has(inv.messageId)) continue;
    seen.add(inv.messageId);
    store.queue.push({ ...inv, queuedAt: new Date().toISOString() });
    added++;
  }
}

// Oudste eruit als het te lang wordt. Een rij die niemand ophaalt is een lek,
// geen archief.
if (store.queue.length > MAX_QUEUE) store.queue = store.queue.slice(-MAX_QUEUE);

return [{ json: { added, inQueue: store.queue.length } }];

// LaVega vraagt de rij op. Wij geven hem en gooien hem weg: één lezer, één keer.
//
// Weggooien na uitlezen is bewust. Wat de browser heeft, staat versleuteld in
// de kluis; wat hier blijft staan, staat onversleuteld in de n8n-database. Hoe
// korter dat duurt, hoe beter.
const store = $getWorkflowStaticData('global');
const queue = Array.isArray(store.queue) ? store.queue : [];
store.queue = [];
return [{ json: { invoices: queue, servedAt: new Date().toISOString() } }];
